        monday = d - datetime.timedelta(days=d.weekday()) + datetime.timedelta(days=7 * offset)
        x = monday + datetime.timedelta(days=6)
        while x >= monday and not isbd(x):
            x = x - ONE
        return x if x >= monday else None
