                    elif keep.count('.') > 1:
                        keep = keep.replace('.', '')
                    if ',' not in keep and keep.count('.') <= 1:
                        whole, dot, frac = keep.partition('.')
                        c = int(whole or '0') * 100 + int((frac + '00')[:2])
                        if len(frac) > 2 and frac[2] >= '5':
