    def fmt_cents(c):
        return ('-' if c < 0 else '') + str(abs(c) // 100) + '.' + ('0' + str(abs(c) % 100))[-2:]
    def amt(c):
        return (fmt_cents(c) if c is not None else 'an unknown amount') + (' ' + CFG['currency'] if CFG['currency'] and c is not None else '')
    def fill(tpl, p):
        out = tpl
        for k in list(p.keys()):
