        i = 0
        while i < len(t):
            if t[i] == '{' and t[i - 1:i] != '{' and t[i + 1:i + 2] != '{':
                j = t.find('}', i)
                head = t[i + 1:j] if j > i else ''
                if head and not head[0].isdigit() and head.replace('_', 'a').isalnum() and t[j + 1:j + 2] != '}':
                    i = j + 1
                    continue
            out = out + t[i]
            i = i + 1
        return out
    def unbrace(t):
