        vars['allowed_' + pid] = ','.join(allowed_iso)
        vars['allowed_spoken_' + pid] = ','.join(allowed_say[:CFG['spoken_limit']])
        vars['allowed_count_' + pid] = str(len(allowed_iso))
        if until:
