                a = parts[0] + '-' + parts[1].zfill(2) + '-' + parts[2].zfill(2)
            elif len(parts) == 3 and len(parts[2]) == 4:
                a = parts[2] + '-' + parts[1].zfill(2) + '-' + parts[0].zfill(2)
